from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from oauth2_provider.models import RefreshToken

class RefreshTokenIntrospectView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, token_key):
        caller_app = getattr(request.auth, 'application', None)
        # Scope refresh token lookup strictly to calling client's application
        refresh_token = RefreshToken.objects.select_related("access_token", "application").filter(
            token=token_key,
            application=caller_app
        ).first()
        if not refresh_token:
            return Response({"active": False}, status=status.HTTP_404_NOT_FOUND)

        return Response({
            "active": not refresh_token.revoked,
            "application_client_id": refresh_token.application.client_id,
            "scope": refresh_token.access_token.scope if refresh_token.access_token else "",
            "user_id": refresh_token.user_id
        })
